def editmatch(sub, out):
    # try all translations of sub within out; count cells of out not covered + sub cells outside
    h,w=sub.shape; H,W=out.shape
    best=None
    for dr in range(-h, H+1):
        for dc in range(-w, W+1):
            cover=np.zeros_like(out,bool)
            ok=True
            for r in range(h):
                for c in range(w):
                    if sub[r,c]:
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W: cover[rr,cc]=True
            miss=int((out&~cover).sum())  # out cells not covered by shape
            extra=0
            for r in range(h):
                for c in range(w):
                    if sub[r,c]:
                        rr,cc=r+dr,c+dc
                        if not(0<=rr<H and 0<=cc<W) or not out[rr,cc]: extra+=1
            sc=miss+extra
            if best is None or sc<best[0]: best=(sc,dr,dc,miss,extra)
    return best

