import numpy as np, itertools
from scipy import ndimage as ndi

def comps(g,v,conn=4):
    st=ndi.generate_binary_structure(2,1 if conn==4 else 2)
    lab,nn=ndi.label(g==v,structure=st)
    return [np.argwhere(lab==i) for i in range(1,nn+1)]

def show(cells):
    ys=cells[:,0]-cells[:,0].min(); xs=cells[:,1]-cells[:,1].min()
    h,w=ys.max()+1,xs.max()+1
    m=np.zeros((h,w),int); m[ys,xs]=1
    return [''.join('#' if x else '.' for x in r) for r in m]

def editdist(a,b):
    # a,b boolean grids same shape; count mismatch
    return int((a!=b).sum())

def best_match(cells,outv):
    # outv: output grid values>0 as bool; try all offsets
    ys=cells[:,0]; xs=cells[:,1]
    H,W=outv.shape
    best=(10**9,None)
    for dr in range(-8,H):
        for dc in range(-8,W):
            m=np.zeros((H,W),bool)
            r,c=ys+dr,xs+dc
            ok=(r>=0)&(r<H)&(c>=0)&(c<W)
            m[r[ok],c[ok]]=True
            d=int((m!=outv).sum())
            if d<best[0]: best=(d,(dr,dc))
    return best

